{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP (Port 80) Access",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows ingress from any source (0.0.0.0/0) on port 80. This exposes the web server to unencrypted HTTP traffic, which can lead to data interception or man-in-the-middle attacks. Port 80 should typically be restricted or redirected to HTTPS."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"digital-asset-trading-platform-firewall-web\"\n  network = google_compute_network.digital_asset_trading_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"443\", \"8080\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n}",
  "fix_summary": "Removed port 80 from the allowed ports list in the firewall rule to prevent unencrypted HTTP traffic from being accepted from the internet, enforcing HTTPS (443) and the application port (8080) instead."
}
